const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tiers = {BUTTON4:1,BUTTON5:1,MWU:1,MWD:1,Q:2,E:2,R:2,F:2,C:2,'2':3,'3':3,'4':3,S:3,G:4,'1':4,X:4,Z:4,'5':5,T:5,V:5};
