const mods = {normal:'',shift:'SHIFT-',ctrl:'CTRL-',alt:'ALT-'};
const niceMods = {normal:'N',shift:'S',ctrl:'C',alt:'A'};
const bindable = new Set(['Esc','Tab','Enter','Space','NumLock','F1','F2','F3','F4','F5','F6','F7','F8','F9','F10','`','1','2','3','4','5','6','7','8','9','0','-','=','Q','W','E','R','T','Y','U','I','O','P','[',']','A','S','D','F','G','H','J','K','L',';','\'','Z','X','C','V','B','N','M',',','.','/','BUTTON4','BUTTON5','MWU','MWD']);
const rows = [
 [{k:'Esc',w:'wide'},...['F1','F2','F3','F4','F5','F6','F7','F8','F9','F10'].map(k=>({k}))],
 [{k:'`'},...['1','2','3','4','5','6','7','8','9','0','-','='].map(k=>({k})),{k:'Backspace',w:'wide2'}],
 [{k:'Tab',w:'wide'},...['Q','W','E','R','T','Y','U','I','O','P','[',']'].map(k=>({k}))],
 [{k:'Caps',w:'wide2'},...['A','S','D','F','G','H','J','K','L',';','\''].map(k=>({k})),{k:'Enter',w:'wide'}],
 [{k:'Shift',w:'wide2'},...['Z','X','C','V','B','N','M',',','.','/'].map(k=>({k})),{k:'Shift',w:'wide2'}],
 [{k:'Ctrl',w:'wide'},{k:'Win',w:'wide'},{k:'Alt',w:'wide'},{k:'Space',w:'space'},{k:'Alt',w:'wide'},{k:'Ctrl',w:'wide'}]
];
// A fresh Forever character uses either Classic keyboard-turning or Enhanced strafing.
// Explicit overrides live in profile.bindings; untouched defaults remain visual (and are not exported).
const DEFAULT_ACTIONS = new Map();
const action=(command,name)=>({id:'fresh:'+command,name,category:'Game Controls',type:'command',command,scope:'Fresh-install reference',priority:3});
function freshDefaults(){
 const d=new Map(), set=(k,m,a)=>d.set(k+'|'+m,a);
 // Only documented/common bindings are included; not every client option has identical defaults.
 for(const a of DATA.general){
  if(!['ASSISTTARGET','TARGETLASTHOSTILE'].includes(a.command))set(a.defaultKey,a.defaultMod,a);
 }
 ['1','2','3','4','5','6','7','8','9','0','-','='].forEach((key,i)=>set(key,'normal',action('ACTIONBUTTON'+(i+1),'Action Bar '+(i+1))));
 set('W','normal',action('MOVEFORWARD','Move forward'));
 set('S','normal',action('MOVEBACKWARD','Move backward'));
 set('A','normal',action(ui.preset==='classic'?'TURNLEFT':'STRAFELEFT',ui.preset==='classic'?'Turn left':'Strafe left'));
 set('D','normal',action(ui.preset==='classic'?'TURNRIGHT':'STRAFERIGHT',ui.preset==='classic'?'Turn right':'Strafe right'));
 if(ui.preset==='classic'){
  const assist=DATA.general.find(a=>a.command==='ASSISTTARGET');if(assist)set('F','normal',assist);
  set('Q','normal',action('STRAFELEFT','Strafe left'));
  set('E','normal',action('STRAFERIGHT','Strafe right'));
 }
 // Familiar fresh-character targeting and social shortcuts (client settings may vary).
 set('F1','normal',action('TARGETSELF','Target self'));
 for(let n=1;n<=4;n++)set('F'+(n+1),'normal',action('TARGETPARTYMEMBER'+n,'Target party '+n));
 set('Enter','normal',action('OPENCHAT','Open chat'));
 set('R','normal',action('REPLY','Reply whisper'));
 set('Z','normal',action('TOGGLEWEAPON','Sheathe weapons'));
 set('X','normal',action('SITORSTAND','Sit / Stand'));
 set('MWU','normal',action('CAMERAZOOMIN','Zoom in'));
 set('MWD','normal',action('CAMERAZOOMOUT','Zoom out'));
 // SHIFT + 1..6 changes the current action bar in traditional Classic controls.
 if(ui.preset==='classic')for(let n=1;n<=6;n++)set(String(n),'shift',action('SHAPESHIFTBUTTON'+n,'Action bar page '+n));
 return d;
}
function effectiveAt(slot){
 const x=p().bindings;
 if(Object.prototype.hasOwnProperty.call(x,slot)){
  const value=x[slot];return {id:value,ability:value?spellById(value):null,isDefault:false,cleared:!value};
 }
 const a=freshDefaults().get(slot);
 return {id:a?.id||null,ability:a||null,isDefault:!!a,cleared:false};
}
function effectiveEntries(){
 const result = new Map(freshDefaults());
 for(const [slot,id] of Object.entries(p().bindings)){
  if(!id)result.delete(slot);
  else result.set(slot,spellById(id)||{id,name:'Unavailable ability'});
 }
 return result;
}
const mouse = [{key:'BUTTON4',label:'Mouse 4',icon:'◁'},{key:'BUTTON5',label:'Mouse 5',icon:'▷'},{key:'MWU',label:'Wheel up',icon:'↑'},{key:'MWD',label:'Wheel down',icon:'↓'}];
let state;
let ui={layer:'primary',category:'All',search:'',selected:null,rotation:'single',preset:'enhanced',libraryTab:'abilities'};
let toastTimer;
function profileId(){return 'p'+Date.now().toString(36)+Math.random().toString(36).slice(2,8)}
function starter(cls='Mage',spec='Frost',race='Gnome'){
 return {id:profileId(),name:`${spec} ${cls}`,cls,spec,race,bindings:{},level:60,preset:'enhanced',talents:[],custom:[],created:Date.now(),updated:Date.now()};
}
function load(){
 try{
  const raw = JSON.parse(localStorage.getItem(STORE_KEY));
  if(raw && raw.version===1 && Array.isArray(raw.profiles) && raw.profiles.length && raw.profiles.length < 501){
   state = {version:1,profiles:raw.profiles,active:raw.active,customCategories:Array.isArray(raw.customCategories)?raw.customCategories:[]};
   if(!state.profiles.some(p=>p.id===state.active))state.active=state.profiles[0].id;
   return;
  }
 }catch(e){console.warn('Saved layouts could not be opened',e)}
 const p=starter();state={version:1,profiles:[p],active:p.id,customCategories:[]};save();
}
function save(){
 try {localStorage.setItem(STORE_KEY,JSON.stringify(state));$('#save-status').textContent='● Saved to this browser'}
 catch(e){$('#save-status').textContent='⚠ Storage unavailable';notify('Storage unavailable — export a JSON backup now.')}
}
function p(){return state.profiles.find(it=>it.id===state.active)||state.profiles[0]}
function mutate(fn){fn(p());p().updated=Date.now();save();render()}
function activeSpells(){return v2Abilities(p().cls,p().spec,p().race,p().custom)}
function eligible(){return activeSpells().filter(a=>!a.talent || p().talents.includes(a.id))}
function spellById(id){return activeSpells().find(a=>a.id===id) || [...freshDefaults().values()].find(a=>a.id===id)}
function assignedCount(id){return Object.values(p().bindings).filter(v=>v===id).length}
function categories(){return [...new Set([...DATA.groups.filter(x=>x!=='Custom'),...state.customCategories,'Custom'])]}
function notify(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200)}
function setOptions(el,items,value){el.innerHTML=items.map(k=>`<option value="${esc(k)}">${esc(k)}</option>`).join('');el.value=value}
function syncSelectors(){
 const x=p();
 setOptions($('#class-select'),Object.keys(DATA.spells),x.cls);
 setOptions($('#spec-select'),Object.keys(DATA.spells[x.cls].specs),x.spec);
 setOptions($('#race-select'),DATA.playable[x.cls],x.race);
 setOptions($('#level-select'),Array.from({length:60},(_,i)=>String(i+1)),String(x.level||60));
 
 $('#selected-class-label').textContent=x.cls;
 $('#selected-profile-label').textContent=x.name;
 $('#class-symbol').textContent=({Mage:'✧',Druid:'☘',Hunter:'➶',Rogue:'⚔',Priest:'✚',Paladin:'✦',Warrior:'⚒',Shaman:'ϟ',Warlock:'◆'})[x.cls]||'✦';
 $('#profile-count').textContent=String(state.profiles.length);
 const options=activeSpells().filter(a=>a.talent);
 $('#talent-count').textContent=String(options.filter(a=>x.talents.includes(a.id)).length);
}
function switchCombo(overrides){
 const old=p();let n={cls:old.cls,spec:old.spec,race:old.race,...overrides};
 if(!(n.spec in DATA.spells[n.cls].specs))n.spec=Object.keys(DATA.spells[n.cls].specs)[0];
 if(!DATA.playable[n.cls].includes(n.race))n.race=DATA.playable[n.cls][0];
 let existing=(old.cls===n.cls && old.spec===n.spec && old.race===n.race) ? old : state.profiles.filter(i=>i.cls===n.cls && i.spec===n.spec && i.race===n.race).sort((a,b)=>(b.updated||0)-(a.updated||0))[0];
 if(!existing){existing=starter(n.cls,n.spec,n.race);existing.preset=old.preset||'enhanced';state.profiles.push(existing);notify('Created a new layout for this character setup')}
 state.active=existing.id;ui.selected=null;ui.search='';ui.category='All';$('#ability-search').value='';save();render();
}
function updateRace(race){mutate(x=>{x.race=race;x.bindings=Object.fromEntries(Object.entries(x.bindings).filter(([k,id])=>!id.startsWith('racial:')))});notify('Race updated; old racial bindings removed')}
function render(){updateForeverStatus();ui.preset=p().preset||'enhanced';$('#default-preset').value=ui.preset;syncSelectors();renderCategories();renderAbilities();renderLibraryTabs();renderKeyboard();renderMouse();renderGeneralControls();renderStats();renderSuggestions();renderWarnings();renderRotation();renderSelection()}
function renderSelection(){
 const el=$('#clear-selection');const a=ui.selected&&spellById(ui.selected);
 el.classList.toggle('has-selected',!!a);el.textContent=a ? '✦ '+a.name+'  ×' : 'No spell selected';el.title=a?'Click to deselect':'Choose an ability to assign';
}
function renderLibraryTabs(){
 for(const tab of document.querySelectorAll('[data-library-tab]')){
  const active=tab.dataset.libraryTab===ui.libraryTab;
  tab.classList.toggle('active',active);
  tab.setAttribute('aria-selected',String(active));
  tab.tabIndex=active?0:-1;
 }
 $('#pane-abilities').hidden=ui.libraryTab!=='abilities';
 $('#pane-controls').hidden=ui.libraryTab!=='controls';
}
function renderCategories(){
 let btn='<button class="category-button '+(ui.category==='All'?'active':'')+'" data-category="All">All</button>';
 for(const category of categories().filter(x=>x!=='Game Controls'&&x!=='Targeting')){
  const num=activeSpells().filter(a=>a.category===category && a.type!=='command').length;
  if(!num && !state.customCategories.includes(category))continue;
  btn+=`<button class="category-button ${ui.category===category?'active':''}" data-category="${esc(category)}">${esc(category)}</button>`;
 }
 btn+='<button class="category-button" data-action="add-category" title="Add a custom ability category">＋ Category</button>';
 $('#category-list').innerHTML=btn;
}
