const detailsByCategory={Damage:'Deals damage to enemies as part of your attack or damage rotation.',Defensive:'Helps you survive incoming damage or dangerous mechanics.',Movement:'Moves or repositions your character in combat or exploration.',Control:'Disrupts, restricts, interrupts or controls enemies.',Utility:'Provides a non-damage benefit such as a buff, dispel, or special interaction.',Healing:'Restores health to yourself or an ally.',Cooldown:'A situational ability intended for an important timing window.',Racial:'An active racial ability with a specialised effect.',Targeting:'Changes your currently selected target.','Game Controls':'Opens a game interface or performs an ordinary game action.',Custom:'A player-defined action; verify its name and effect in-game.'};
function details(a){
 const d=SPELL_DETAILS[a.id]||{};
 const source=FOREVER_ICONS[a.id];
 if(source){
  const reliable=source.sourceQuality==='beta'||source.sourceQuality==='demo';
  return {
   cast:source.cast||'Not listed',cd:source.cooldown||'Not specified',
   desc:source.desc||d.desc||detailsByCategory[a.category]||'No description recorded in source',
   verified:reliable,
   source:`Talents Forever · ${FOREVER_META.generated} export · ${FOREVER_META.build}; ${source.rank||'unranked'} · ${source.sourceQuality==='classic'?'Classic fallback text':source.sourceQuality||'source unknown'}`
  };
 }
 return {cast:d.cast||(a.type==='command'?'Not applicable':'Check in-game'),cd:d.cd||(a.type==='command'?'Not applicable':'Check in-game'),desc:d.desc||detailsByCategory[a.category]||'Review this ability in your spellbook.',verified:!!d.verified,source:d.source||'Illustrative reference, not a verified Forever tooltip'};
}

function spellArt(a){
 if(!a)return 0;
 const n=a.name.toLowerCase();
 if(/fire|flame|blast wave|immolat|pyro|combust|scorch/.test(n))return 0;
 if(/frost|ice|blizzard|cold|freezing|chill/.test(n))return 1;
 if(/arcane|mana|magic|polymorph|spellbook|comprehend/.test(n))return 2;
 if(/lightning|shock|chain|storm|thunder/.test(n))return 3;
 if(/holy|divine|blessing|judgement|shield of light/.test(n))return 4;
 if(/nature|root|moon|leaf|faerie|rejuvenation|regrowth/.test(n))return 5;
 if(/sword|strike|heroic|cleave|mortal|execute|rend|whirl/.test(n))return 6;
 if(/shield|barrier|block|evasion|defensive/.test(n))return 7;
 if(/stealth|vanish|shadowstep|sprint|backstab|cheap shot/.test(n))return 8;
 if(/poison|venom|serpent|sting|envenom/.test(n))return 9;
 if(/wolf|beast|pet|call pet|bear|cat form|rake|claw/.test(n))return 10;
 if(/shot|arrow|bow|trap/.test(n))return 11;
 if(/heal|prayer|renew|flash|restoration|penance/.test(n))return 15;
 if(/blink|dash|travel|ghost wolf|charge/.test(n))return 16;
 if(/death|bone|soul|curse|bane|undead|shadow bolt/.test(n))return 17;
 if(/potion|healthstone|conjure|item/.test(n))return 19;
 if(/wind|gust|tornado/.test(n))return 21;
 if(/control|interrupt|kick|counterspell|fear|blind|sap/.test(n))return 26;
 if(a.category==='Racial')return 31;
 const cat={Damage:6,Defensive:7,Movement:16,Control:26,Utility:28,Healing:33,Cooldown:34,Racial:31,'Game Controls':32,Targeting:28,Custom:35};
 return cat[a.category]??2;
}
function utilityType(name){
 const n=(name||'').toLowerCase();
 if(/spellbook/.test(n)) return 'book';
 if(/world map|map/.test(n)) return 'map';
 if(/quest/.test(n)) return 'scroll';
 if(/friends|social/.test(n)) return 'person';
 if(/guild|community|group|party/.test(n)) return 'group';
 if(/character/.test(n)) return 'shield';
 if(/talents?/.test(n) && !/legacy/.test(n)) return 'spark';
 if(/legacy/.test(n)) return 'star';
 if(/bags?|backpack/.test(n)) return 'bag';
 if(/auto run/.test(n)) return 'boot';
 if(/chat|reply/.test(n)) return 'chat';
 if(/mail/.test(n)) return 'mail';
 if(/mount/.test(n)) return 'horse';
 if(/target/.test(n)) return 'target';
 if(/assist/.test(n)) return 'assist';
 if(/interface|options|settings/.test(n)) return 'gear';
 if(/sit/.test(n)) return 'chair';
 if(/weapon/.test(n)) return 'sword';
 return 'gear';
}
