// WoW Forever icon mapping: no fuzzy-name guesses. Use approved client records with exact IDs.
const FOREVER_SOURCE = window.KBF_FOREVER_SOURCE;
const FOREVER_META={
 source:'Talents Forever · included source data',
 build:[...new Set(Object.values(FOREVER_SOURCE.spellbooks).map(b=>b.build).filter(Boolean))].join(', '),
 generated:FOREVER_SOURCE.generated,
 attribution:'https://talentsforever.com'
};
// This is an in-app copy of the user-provided CC BY 4.0 export. No JSON import,
// browser storage, remote database or API key is required to obtain the data.
const FOREVER_ICONS={};
function iconUrlFor(name){
 if(typeof name!=='string'||!/^[a-z0-9_]{3,120}$/i.test(name))return null;
 return 'https://wow.zamimg.com/images/wow/icons/large/'+name.toLowerCase()+'.jpg';
}
function makeForeverRecord(icon, record, name, type='talentsforever'){
 if(!iconUrlFor(icon))return null;
 const lines=(record?.l||[]).flat().filter(x=>typeof x==='string').map(x=>x.trim()).filter(Boolean);
 const cast=lines.find(x=>/^(instant|passive|channeled|channelled|\d+(?:\.\d+)?\s*(?:sec|second)s?\s*cast)$/i.test(x))||
   lines.find(x=>/\b(?:cast|channeled|channelled)\b/i.test(x))||'Not listed';
 const cooldown=lines.find(x=>/\b(?:sec|second|min|minute|hour)s?\s*cooldown\b/i.test(x))||'Not specified';
 return {
  icon:String(icon).toLowerCase(),spellId:Number.isInteger(Number(record?.id))&&Number(record.id)>0?Number(record.id):null,
  name,rank:record?.rank||'',cast,cooldown,desc:String(record?.d||'').trim(),
  sourceType:type,source:String(record?.src||record?.s||'client export').slice(0,200),
  sourceQuality:record?.s||'unknown',learned:record?.lv||''
 };
}
function buildForeverMap(){
 const books=FOREVER_SOURCE.spellbooks;
 const ranksBySpell=new Map();
 for(const [key,detail] of Object.entries(FOREVER_SOURCE.spell_desc)){
  if(!detail||typeof detail!=='object')continue;
  const parts=key.split('|');if(parts.length!==3)continue;
  const name=parts[0]+':'+parts[1];
  const match=parts[2].match(/^Rank (\d+)$/i);
  if(!ranksBySpell.has(name))ranksBySpell.set(name,[]);
  ranksBySpell.get(name).push({...detail,rank:parts[2],rankNum:match?Number(match[1]):0});
 }
 for(const ranks of ranksBySpell.values())ranks.sort((a,b)=>b.rankNum-a.rankNum);
 for(const [cls,book] of Object.entries(books)){
  for(const [name,icon] of Object.entries(book.icons||{})){
   const record=(ranksBySpell.get(cls+':'+name)||[]).find(r=>Number.isInteger(Number(r.id))&&Number(r.id)>0);
   if(!record)continue;
   const result=makeForeverRecord(icon,record,name);
   if(result)FOREVER_ICONS[cls+':'+name]=result;
  }
 }
 // The client export has a separate explicit icon table for active racial abilities.
 for(const faction of Object.values(FOREVER_SOURCE.racials||{})){
  if(!Array.isArray(faction))continue;
  for(const race of faction){
   for(const ability of race.abilities||[]){
    const [name,description,icon]=ability;
    if(typeof name!=='string'||!iconUrlFor(icon))continue;
    const label=String(description||'');
    const cast=label.match(/\bInstant\b/i)?.[0]||'Not listed';
    const cooldown=label.match(/\b\d+(?:\.\d+)?\s*(?:sec|min)\s*cooldown\b/i)?.[0]||'Not specified';
    const id='racial:'+name;
    if(!FOREVER_ICONS[id])FOREVER_ICONS[id]={
     spellId:null,icon:String(icon).toLowerCase(),name,cast,cooldown,desc:label,
     rank:'',sourceType:'talentsforever-racial',source:'racial abilities from the included client export',sourceQuality:'beta'
    };
   }
  }
 }
}
buildForeverMap();

// v2: spell availability comes from the supplied 30 October 2026 Forever export.
// Existing class:name saved binding IDs are deliberately retained.
function v2Category(name,tab){
 const n=name.toLowerCase();
 if(/heal|renew|rejuven|regrowth|restor|mend|flash of light|holy light|penance|prayer|lifebloom|tranquil|resurrection|revive/.test(n))return 'Healing';
 if(/shield|barrier|block|protection|ward|wall|ice block|last stand|evasion|barkskin|sacrifice|survival instinct|stoneform/.test(n))return 'Defensive';
 if(/blink|sprint|dash|charge|intercept|travel form|ghost wolf|aspect of the cheetah|disengage|teleport/.test(n))return 'Movement';
 if(/interrupt|kick|counterspell|silence|polymorph|fear|sap|stun|stasis|nova|trap|sheep|hex|gouge|blind|bash|entangling root|scatter shot/.test(n))return 'Control';
 if(/conjure|portal|water walking|summon|detect|dispel|purge|remove curse|cure|cleans|resurrection|lockpick|pick lock|ritual|track|aspect|blessing|aura|totem|mark of the wild|intellect|fortitude|buff|feed pet|revive pet|mount|profession|mining|herbalism/.test(n))return 'Utility';
 if(/bloodlust|heroism|berserk|combustion|arcane power|adrenaline rush|death wish|rapid fire|cold snap/.test(n))return 'Cooldown';
 return 'Damage';
}
function v2RankInfo(row, level){
 const rank=row.ranks.filter(r=>!r.level || r.level<=level);
 return rank[rank.length-1]||null;
}
function v2ParseTiming(lines,extra=''){
 const all=[...lines,extra].filter(Boolean).join(' | ');
 const cast=all.match(/(?:\d+(?:\.\d+)?\s*(?:sec|second)s?\s*cast|instant(?: cast)?|channeled|channelled|passive)/i);
 const cd=all.match(/\d+(?:\.\d+)?\s*(?:sec|min|minute|hour)s?\s*cooldown/i);
 return {cast:cast?cast[0]:'Not listed',cooldown:cd?cd[0]:'Not specified'};
}
function v2Racials(cls,race){
 const rec=FOREVER_V2_DATA.racials[race];if(!rec)return [];
 return rec.abilities.filter(a=>!/^(increases|improves|reduces|grants|allows|your |you |chance)/i.test(a.desc.trim()) || /instant|cooldown|activate|usable/i.test(a.desc)).map(a=>{
  const id='racial:'+a.name;const d=v2ParseTiming([],a.desc);
  FOREVER_ICONS[id]={spellId:null,icon:a.icon,name:a.name,cast:d.cast,cooldown:d.cooldown,desc:a.desc,rank:'',sourceQuality:'beta',sourceType:'talentsforever-racial'};
  return {id,name:a.name,category:'Racial',type:'spell',scope:'Racial',priority:2,level:1};
 });
}
function v2Abilities(cls,spec,race,custom=[]){
 const out=[];const level=Math.min(60,Math.max(1,Number(p().level)||60));
 for(const [name,row] of Object.entries(FOREVER_V2_DATA.spellbooks[cls]||{})){
  const rank=v2RankInfo(row,level);
  const info=row.talentInfo;
  if(!rank && !row.talent)continue;
  if(!rank && row.talent && level<Math.max(10,Number(info?.row||1)*5))continue;
  const id=cls+':'+name;
  const d=v2ParseTiming(rank?.lines||[],info?.cost||'');
  const icon=row.icon;
  FOREVER_ICONS[id]={spellId:rank?.id||null,icon,name,rank:rank?.rank||'',cast:d.cast,cooldown:d.cooldown,desc:rank?.desc||info?.desc||'',sourceType:'talentsforever',sourceQuality:rank?.quality||'beta',learned:rank?.level||''};
  const cat=v2Category(name,row.tab); const priority=cat==='Damage'||cat==='Healing'?2:(cat==='Control'||cat==='Movement'?1:3);
  out.push({id,name,category:cat,priority,scope:'Class',type:'spell',talent:!!row.talent,level:rank?.level||1,rank:rank?.rank||'',tree:info?.tree||''});
 }
 return [...out,...v2Racials(cls,race),...(custom||[])];
}

